import { expect, expectStatus, test } from "../../fixtures";

test.describe("vendor lifecycle", () => {
  test(
    "once a vendor is sent back, its other documents cannot be decided",
    { tag: "@LIF-03" },
    async ({ apiAs, factory }) => {
      // Arrange
      const { documents, extractions } = await factory.vendorInReview({ as: "member" });
      const reviewer = await apiAs("reviewer");
      await expectStatus(
        await reviewer.post(`/api/extractions/${extractions.w9.id}/decision`, {
          data: { decision: "reject", note: "W-9 is unsigned" },
        }),
        200,
      );

      // Act
      const response = await reviewer.post(`/api/extractions/${extractions.contract.id}/decision`, {
        data: { decision: "approve" },
      });

      // Assert
      const body = await expectStatus(response, 409);
      expect(body.error.code).toBe("vendor_not_in_review");
      expect((await factory.extraction(documents.contract.id, "reviewer")).status).toBe("pending_review");
    },
  );
});
